.container {
  max-width: 800px;
  margin: 0 auto;
  padding: 40px 20px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: #333;
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
}

.title {
  font-size: 24px;
  font-weight: 600;
  margin: 0;
}

.syncButton {
  background-color: #0070f3;
  color: white;
  border: none;
  padding: 10px 16px;
  border-radius: 6px;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: background-color 0.2s;
}

.syncButton:hover {
  background-color: #0051a2;
}

.tableContainer {
  border: 1px solid #eaeaea;
  border-radius: 8px;
  overflow: hidden;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.05);
}

.table {
  width: 100%;
  border-collapse: collapse;
}

.th {
  background-color: #fafafa;
  text-align: left;
  padding: 12px 16px;
  font-weight: 600;
  font-size: 14px;
  color: #666;
  border-bottom: 1px solid #eaeaea;
}

.td {
  padding: 12px 16px;
  font-size: 14px;
  border-bottom: 1px solid #eaeaea;
}

.tr:last-child .td {
  border-bottom: none;
}

.tr:hover {
  background-color: #f9f9f9;
}

.price {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.id {
  color: #999;
  font-family: monospace;
  font-size: 12px;
}

