import { unstable_cache, revalidateTag } from 'next/cache';
import { getAllProducts } from '@/lib/db';
import styles from './page.module.css';

// Cache the product fetching
const getCachedProducts = unstable_cache(
  async () => getAllProducts(),
  ['products-list'],
  { tags: ['products'] }
);

export default async function Page() {
  const products = await getCachedProducts();

  // Inline Server Action
  async function syncCatalog() {
    'use server';
    revalidateTag('products');
  }

  return (
    <div className={styles.container}>
      <header className={styles.header}>
        <h1 className={styles.title}>Product Catalog</h1>
        <form action={syncCatalog}>
          <button type="submit" className={styles.syncButton}>
            Sync Latest Catalog
          </button>
        </form>
      </header>

      <div className={styles.tableContainer}>
        <table className={styles.table}>
          <thead>
            <tr>
              <th className={styles.th}>ID</th>
              <th className={styles.th}>Product Name</th>
              <th className={`${styles.th} ${styles.price}`}>Price</th>
            </tr>
          </thead>
          <tbody>
            {products.map((product: any) => (
              <tr key={product.id} className={styles.tr}>
                <td className={styles.td}>
                  <span className={styles.id}>#{product.id}</span>
                </td>
                <td className={styles.td}>{product.name}</td>
                <td className={`${styles.td} ${styles.price}`}>
                  ${product.price.toFixed(2)}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <p style={{ marginTop: '1rem', fontSize: '12px', color: '#888', textAlign: 'center' }}>
        Catalog data is cached. Sync to refresh.
      </p>
    </div>
  );
}

